// The responsibility cascade as data — extracted from server/routes/ai.js so the route
// that publishes it and the walker that executes it share one copy.
//
// Source of truth, and nothing here is invented:
//
//   sampleData/HAL PURCHASE FORMATS dt 22.06.2026/
//       Note & Format Generation Stages and responsibility cascadeing.xlsx  [Sheet1]
//
// The sheet recognises exactly two actors. Row 23, "Note Can only be Generated by", names
// the single agency allowed to raise the notes in each stage column — which is why acting
// out of turn is refused here rather than merely warned about, and the file has to be
// handed over first.
//
// The sheet holds no conditional logic of its own: it says WHICH notes are possible at a
// stage and WHO may raise them, never WHEN to prefer one. So every edge is selectable, and
// the only two preferences (pnc_required, retender_required) come from rules.js, are
// labelled with their rule name, and are never binding.

export const AGENCIES = ['Indenting', 'Tendering'];
export const START = 'provisioning';

