export const optionAt = (nodeId, noteId) =>
  (CASCADE_NODES[nodeId]?.options ?? []).find((o) => o.noteId === noteId) ?? null;

export const otherAgency = (a) => (a === 'Indenting' ? 'Tendering' : 'Indenting');

export default {
  AGENCIES, START, SHORT_CLOSURE_MESSAGE, STAGE_META, CASCADE_NODES, POST_TENDER_FORMATS,
  FORMAT_OWNER, FORMAT_TITLE, PREREQ_FORMATS, CHECKLIST, optionAt, otherAgency
};
